-- Проекты (страница /projects/ и карточки на главной) и кейсы — построенные дома. Редактируются в админке.
-- data — все поля карточки (список и проверка полей — src/catalog.ts); position — порядок на сайте.
-- Начальные записи — демо-проекты и демо-кейсы, которые были в вёрстке.
CREATE TABLE projects (
  id         serial PRIMARY KEY,
  position   integer NOT NULL DEFAULT 0,
  data       jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text
);
CREATE TABLE cases (
  id         serial PRIMARY KEY,
  position   integer NOT NULL DEFAULT 0,
  data       jsonb NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by text
);
INSERT INTO projects (position, data) VALUES
  (0, '{"slug": "tau", "style": "af", "name": "Тау", "name_ky": "Тау", "area": 43, "beds": 1, "baths": 1, "floors": "1 + антресоль", "floors_ky": "1 + антресоль", "text": "Компактный A-frame для выходных или гостевого дома: кухня-гостиная со вторым светом и спальня на антресоли под самым коньком.", "text_ky": "Дем алыш күндөргө же конок үйүнө компакттуу A-frame: экинчи жарыгы бар ашкана-конок бөлмө жана кырдын астындагы антресолдо уктоочу бөлмө.", "price": null, "image": "https://images.pexels.com/photos/19737830/pexels-photo-19737830.jpeg?auto=compress&cs=tinysrgb&w=1000", "on_home": true, "plan": [{"name": "1 этаж", "name_ky": "1-кабат", "w": 6, "h": 5.5, "void": null, "image": null, "rooms": [{"x": 0, "y": 0, "w": 6, "h": 3.5, "name": "Кухня-гостиная", "name_ky": "Ашкана-конок бөлмө"}, {"x": 0, "y": 3.5, "w": 2.4, "h": 2, "name": "Санузел", "name_ky": "Ванна бөлмө"}, {"x": 2.4, "y": 3.5, "w": 3.6, "h": 2, "name": "Прихожая", "name_ky": "Кире бериш"}]}, {"name": "Антресоль", "name_ky": "Антресоль", "w": 6, "h": 5.5, "void": [0, 0, 6, 3.8], "image": null, "rooms": [{"x": 0, "y": 3.8, "w": 6, "h": 1.7, "name": "Спальня", "name_ky": "Уктоочу бөлмө"}]}]}'),
  (1, '{"slug": "karagay", "style": "af", "name": "Карагай", "name_ky": "Карагай", "area": 68, "beds": 2, "baths": 1, "floors": "2", "floors_ky": "2", "text": "A-frame для семьи из трёх-четырёх человек: одна спальня внизу, вторая наверху, просторная кухня-гостиная с панорамным окном.", "text_ky": "Үч-төрт кишилик үй-бүлөгө A-frame: бир уктоочу бөлмө төмөндө, экинчиси өйдөдө, панорамалык терезеси бар кенен ашкана-конок бөлмө.", "price": null, "image": "https://images.pexels.com/photos/9209878/pexels-photo-9209878.jpeg?auto=compress&cs=tinysrgb&w=1000", "on_home": true, "plan": [{"name": "1 этаж", "name_ky": "1-кабат", "w": 7, "h": 7, "void": null, "image": null, "rooms": [{"x": 0, "y": 0, "w": 7, "h": 4, "name": "Кухня-гостиная", "name_ky": "Ашкана-конок бөлмө"}, {"x": 0, "y": 4, "w": 3.5, "h": 3, "name": "Спальня", "name_ky": "Уктоочу бөлмө"}, {"x": 3.5, "y": 4, "w": 2, "h": 3, "name": "Санузел", "name_ky": "Ванна бөлмө"}, {"x": 5.5, "y": 4, "w": 1.5, "h": 3, "name": "Вход", "name_ky": "Кире бериш"}]}, {"name": "2 этаж", "name_ky": "2-кабат", "w": 7, "h": 7, "void": [0, 0, 7, 4.3], "image": null, "rooms": [{"x": 0, "y": 4.3, "w": 7, "h": 2.7, "name": "Спальня 2", "name_ky": "Уктоочу бөлмө 2"}]}]}'),
  (2, '{"slug": "jailoo", "style": "barn", "name": "Жайлау", "name_ky": "Жайлау", "area": 86, "beds": 2, "baths": 1, "floors": "1", "floors_ky": "1", "text": "Одноэтажный барнхаус для постоянной жизни: две спальни, большая кухня-гостиная и постирочная — всё на одном уровне, без лестниц.", "text_ky": "Туруктуу жашоо үчүн бир кабаттуу барнхаус: эки уктоочу бөлмө, чоң ашкана-конок бөлмө жана кир жуучу жай — баары бир деңгээлде, тепкичсиз.", "price": null, "image": "https://images.pexels.com/photos/4626268/pexels-photo-4626268.jpeg?auto=compress&cs=tinysrgb&w=1000", "on_home": true, "plan": [{"name": "1 этаж", "name_ky": "1-кабат", "w": 12, "h": 7.2, "void": null, "image": null, "rooms": [{"x": 0, "y": 0, "w": 6, "h": 7.2, "name": "Кухня-гостиная", "name_ky": "Ашкана-конок бөлмө"}, {"x": 6, "y": 0, "w": 3.4, "h": 4, "name": "Спальня", "name_ky": "Уктоочу бөлмө"}, {"x": 9.4, "y": 0, "w": 2.6, "h": 4, "name": "Спальня 2", "name_ky": "Уктоочу бөлмө 2"}, {"x": 6, "y": 4, "w": 2.2, "h": 3.2, "name": "Холл", "name_ky": "Холл"}, {"x": 8.2, "y": 4, "w": 2, "h": 3.2, "name": "Санузел", "name_ky": "Ванна бөлмө"}, {"x": 10.2, "y": 4, "w": 1.8, "h": 3.2, "name": "Постирочная", "name_ky": "Кир жуучу жай"}]}]}'),
  (3, '{"slug": "alatoo", "style": "barn", "name": "Ала-Тоо", "name_ky": "Ала-Тоо", "area": 120, "beds": 3, "baths": 2, "floors": "2", "floors_ky": "2", "text": "Двухэтажный семейный барнхаус: три спальни, два санузла, гардероб и второй свет над кухней-гостиной с печью.", "text_ky": "Эки кабаттуу үй-бүлөлүк барнхаус: үч уктоочу бөлмө, эки ванна бөлмө, гардероб жана мештүү ашкана-конок бөлмөнүн үстүндө экинчи жарык.", "price": null, "image": "https://images.pexels.com/photos/8112922/pexels-photo-8112922.jpeg?auto=compress&cs=tinysrgb&w=1000", "on_home": true, "plan": [{"name": "1 этаж", "name_ky": "1-кабат", "w": 10, "h": 7, "void": null, "image": null, "rooms": [{"x": 0, "y": 0, "w": 6, "h": 7, "name": "Кухня-гостиная", "name_ky": "Ашкана-конок бөлмө"}, {"x": 6, "y": 0, "w": 4, "h": 3.6, "name": "Спальня", "name_ky": "Уктоочу бөлмө"}, {"x": 6, "y": 3.6, "w": 2, "h": 3.4, "name": "Санузел", "name_ky": "Ванна бөлмө"}, {"x": 8, "y": 3.6, "w": 2, "h": 3.4, "name": "Прихожая", "name_ky": "Кире бериш"}]}, {"name": "2 этаж", "name_ky": "2-кабат", "w": 10, "h": 7, "void": [0, 5, 10, 2], "image": null, "rooms": [{"x": 0, "y": 0, "w": 3.6, "h": 3.4, "name": "Спальня 2", "name_ky": "Уктоочу бөлмө 2"}, {"x": 3.6, "y": 0, "w": 2.8, "h": 5, "name": "Холл", "name_ky": "Холл"}, {"x": 6.4, "y": 0, "w": 3.6, "h": 3.4, "name": "Спальня 3", "name_ky": "Уктоочу бөлмө 3"}, {"x": 0, "y": 3.4, "w": 3.6, "h": 1.6, "name": "Санузел 2", "name_ky": "Ванна бөлмө 2"}, {"x": 6.4, "y": 3.4, "w": 3.6, "h": 1.6, "name": "Гардероб", "name_ky": "Гардероб"}]}]}');
-- the case links its project by id (the projects above get ids 1–4 in this order)
INSERT INTO cases (position, data) VALUES
  (0, '{"image": "https://images.pexels.com/photos/9209878/pexels-photo-9209878.jpeg?auto=compress&cs=tinysrgb&w=800", "region": "Иссык-Кульская область", "region_ky": "Ысык-Көл облусу", "title": "Дом для отдыха у Иссык-Куля", "title_ky": "Ысык-Көлдөгү эс алуу үйү", "area": "68 м²", "term": "2 месяца", "term_ky": "2 ай", "season": "Осень", "season_ky": "Күз", "story": "Семья хотела дом, куда можно приезжать круглый год. Стройку начали осенью, а Новый год уже встречали в новом доме — с тёплыми полами в подарок.", "story_ky": "Үй-бүлө жыл бою келе турган үй каалаган. Курулушту күзүндө баштап, Жаңы жылды жаңы үйдө тосушту — белекке жылуу пол менен.", "project": 2}'),
  (1, '{"image": "https://images.pexels.com/photos/4626268/pexels-photo-4626268.jpeg?auto=compress&cs=tinysrgb&w=800", "region": "Чуйская область", "region_ky": "Чүй облусу", "title": "Барнхаус для жизни за городом", "title_ky": "Шаардын сыртында жашоо үчүн барнхаус", "area": "86 м²", "term": "2 месяца", "term_ky": "2 ай", "season": "Зима", "season_ky": "Кыш", "story": "Строили зимой: металлический каркас не боится мороза, а отделку начали сразу, без ожидания усадки. Весной семья переехала из квартиры.", "story_ky": "Кышында курдук: металл каркас сууктан коркпойт, ал эми жасалганы отурууну күтпөй эле дароо баштадык. Жазында үй-бүлө батирден көчүп келди.", "project": 3}'),
  (2, '{"image": "https://images.pexels.com/photos/19737830/pexels-photo-19737830.jpeg?auto=compress&cs=tinysrgb&w=800", "region": "Нарынская область", "region_ky": "Нарын облусу", "title": "Гостевые дома для базы отдыха", "title_ky": "Эс алуу базасы үчүн конок үйлөр", "area": "3 × 43 м²", "term": "1,5 месяца", "term_ky": "1,5 ай", "season": "Лето", "season_ky": "Жай", "story": "Три компактных A-frame для гостей базы отдыха. Одинаковая планировка позволила строить дома параллельно и открыть сезон вовремя.", "story_ky": "Эс алуу базасынын конокторуна үч компакттуу A-frame. Бирдей пландоо үйлөрдү катар курууга жана мезгилди өз убагында ачууга мүмкүндүк берди.", "project": 1}');
